(function(){
  const nav=document.querySelector('aside nav'),main=document.querySelector('main');if(!nav||!main)return;window.adminTitles.documents='مراجعة المستندات';
  nav.insertAdjacentHTML('beforeend','<button data-admin-page="documents" onclick="adminPage(\'documents\',this);loadAdminDocuments()">🛡️ <span>مراجعة المستندات</span></button>');
  main.insertAdjacentHTML('beforeend','<section class="admin-page" id="admin-documents"><div class="panel"><div class="panel-head"><div><h2>مستندات الشركاء</h2><p>روابط المعاينة مؤقتة لمدة خمس دقائق ولا تُعرض للعامة.</p></div><button onclick="loadAdminDocuments()">تحديث ↻</button></div><div id="adminDocumentsList"><p class="loading">جارٍ التحميل…</p></div></div></section>');
  const API=window.KHALASA_API_BASE_URL||location.origin,labels={national_id:'بطاقة الرقم القومي',driving_license:'رخصة القيادة',vehicle_license:'رخصة المركبة',criminal_record:'صحيفة الحالة الجنائية',commercial_register:'السجل التجاري',tax_card:'البطاقة الضريبية',owner_id:'بطاقة هوية المالك',activity_license:'ترخيص النشاط'},headers=()=>({'Content-Type':'application/json',Authorization:'Bearer '+(localStorage.getItem('khalasaStaffToken')||'')});
  window.loadAdminDocuments=async()=>{const box=document.getElementById('adminDocumentsList');try{const response=await fetch(API+'/v1/admin/documents',{headers:headers()}),data=await response.json();if(!response.ok)throw new Error();box.replaceChildren();for(const item of (data.documents||[]).filter(x=>x.verification==='pending')){const card=document.createElement('article');card.className='city-user-card';const info=document.createElement('div');const name=document.createElement('b');name.textContent=(item.partner_type==='rider'?'🛵 ':'🏪 ')+item.partner_name;const meta=document.createElement('small');meta.textContent=(labels[item.document_type]||item.document_type)+' · '+item.phone;info.append(name,meta);const actions=document.createElement('div');actions.className='city-user-actions';for(const [label,handler,className] of [['معاينة',()=>viewDocument(item),'table-btn'],['اعتماد',()=>reviewDocument(item,'approved'),'primary'],['رفض',()=>reviewDocument(item,'rejected'),'table-btn']]){const button=document.createElement('button');button.textContent=label;button.className=className;button.onclick=handler;actions.append(button)}card.append(info,actions);box.append(card)}if(!box.children.length)box.textContent='لا توجد مستندات تنتظر المراجعة.'}catch(_){box.textContent='تعذر تحميل المستندات.'}};
  async function viewDocument(item){const response=await fetch(`${API}/v1/admin/documents/${item.partner_type}/${item.id}/view`,{headers:headers()}),data=await response.json();if(!response.ok)return toast('تعذر إنشاء رابط المعاينة');window.open(data.url,'_blank','noopener')}
  async function reviewDocument(item,status){const note=status==='rejected'?prompt('اكتب سبب الرفض ليظهر لصاحب المستند:','المستند غير واضح أو غير مكتمل.')||'المستند يحتاج إعادة رفع.':'';const response=await fetch(`${API}/v1/admin/documents/${item.partner_type}/${item.id}`,{method:'PATCH',headers:headers(),body:JSON.stringify({status,note})});toast(response.ok?(status==='approved'?'تم اعتماد المستند':'تم رفض المستند وإرسال الملاحظة'):'تعذر تحديث المستند');if(response.ok)loadAdminDocuments()}
})();
